CREATE TABLE IF NOT EXISTS schema_version(version integer PRIMARY KEY, installed_at timestamptz NOT NULL DEFAULT now());
INSERT INTO schema_version(version) VALUES(1) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS accounts(id text PRIMARY KEY, subject text NOT NULL UNIQUE, email text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE accounts ADD COLUMN IF NOT EXISTS display_name text;
CREATE TABLE IF NOT EXISTS cloud_workspaces(id text PRIMARY KEY, name text NOT NULL, state text NOT NULL DEFAULT 'pending', provider text, machine_id text, relay_hash text UNIQUE, relay_public_jwk jsonb, generation integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE cloud_workspaces ADD COLUMN IF NOT EXISTS audit_retention_days integer NOT NULL DEFAULT 365;
ALTER TABLE cloud_workspaces ADD COLUMN IF NOT EXISTS edition text NOT NULL DEFAULT 'managed';
CREATE TABLE IF NOT EXISTS memberships(workspace_id text NOT NULL REFERENCES cloud_workspaces(id), account_id text NOT NULL REFERENCES accounts(id), role text NOT NULL CHECK(role IN ('owner','operator','viewer')), revoked boolean NOT NULL DEFAULT false, PRIMARY KEY(workspace_id,account_id));
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY, account_id text NOT NULL REFERENCES accounts(id), csrf_hash text NOT NULL, kind text NOT NULL CHECK(kind IN ('browser','native')), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS authorization_flows(state_hash text PRIMARY KEY, verifier text NOT NULL, nonce text NOT NULL, binding_hash text NOT NULL, client text NOT NULL, redirect_uri text NOT NULL, challenge text, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS native_codes(code_hash text PRIMARY KEY, account_id text NOT NULL REFERENCES accounts(id), challenge text NOT NULL, redirect_uri text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS provision_jobs(id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES cloud_workspaces(id), operation text NOT NULL, request_id text NOT NULL, payload jsonb NOT NULL, state text NOT NULL DEFAULT 'queued', attempts integer NOT NULL DEFAULT 0, receipt jsonb, error text, lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,request_id));
CREATE TABLE IF NOT EXISTS audit_metadata(id text PRIMARY KEY, workspace_id text, actor_id text NOT NULL, operation text NOT NULL, resource text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wallets(workspace_id text PRIMARY KEY REFERENCES cloud_workspaces(id), balance bigint NOT NULL DEFAULT 0 CHECK(balance>=0), reserved bigint NOT NULL DEFAULT 0 CHECK(reserved>=0), hard_limit bigint NOT NULL DEFAULT 0 CHECK(hard_limit>=0), auto_recharge boolean NOT NULL DEFAULT false, frozen boolean NOT NULL DEFAULT false,debt bigint NOT NULL DEFAULT 0 CHECK(debt>=0));
ALTER TABLE wallets ADD COLUMN IF NOT EXISTS frozen boolean NOT NULL DEFAULT false;
ALTER TABLE wallets ADD COLUMN IF NOT EXISTS debt bigint NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS usage_periods(workspace_id text NOT NULL REFERENCES cloud_workspaces(id), period text NOT NULL, spent bigint NOT NULL DEFAULT 0 CHECK(spent>=0), reserved bigint NOT NULL DEFAULT 0 CHECK(reserved>=0), PRIMARY KEY(workspace_id,period));
CREATE TABLE IF NOT EXISTS model_rates(model text PRIMARY KEY, version text NOT NULL, input_microdollars_per_million bigint NOT NULL CHECK(input_microdollars_per_million>=0), output_microdollars_per_million bigint NOT NULL CHECK(output_microdollars_per_million>=0), max_output_tokens integer NOT NULL CHECK(max_output_tokens>0), active boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS model_leases(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES cloud_workspaces(id),actor_id text NOT NULL,run_id text NOT NULL,revoked boolean NOT NULL DEFAULT false,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS usage_reservations(id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES cloud_workspaces(id), run_id text NOT NULL, request_id text NOT NULL, request_hash text NOT NULL, model text NOT NULL, rate_version text NOT NULL, input_rate bigint NOT NULL, output_rate bigint NOT NULL, maximum bigint NOT NULL, charged bigint, input_tokens integer, output_tokens integer, period text NOT NULL, state text NOT NULL CHECK(state IN ('reserved','dispatching','settled','released','uncertain')), provider_receipt text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,request_id));
CREATE TABLE IF NOT EXISTS usage_journal(id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES cloud_workspaces(id), reservation_id text REFERENCES usage_reservations(id), operation text NOT NULL, amount bigint NOT NULL, evidence text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS billing_events(source text NOT NULL, event_id text NOT NULL, workspace_id text NOT NULL REFERENCES cloud_workspaces(id), amount bigint NOT NULL CHECK(amount>0), receipt_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(source,event_id));
CREATE TABLE IF NOT EXISTS billing_refunds(source text NOT NULL,event_id text NOT NULL,purchase_id text NOT NULL,workspace_id text NOT NULL,amount bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(source,event_id));
CREATE TABLE IF NOT EXISTS billing_payment_links(source text NOT NULL,payment_id text NOT NULL,purchase_id text NOT NULL,workspace_id text NOT NULL,amount_paid bigint NOT NULL,PRIMARY KEY(source,payment_id));
CREATE TABLE IF NOT EXISTS entitlements(workspace_id text NOT NULL REFERENCES cloud_workspaces(id), source text NOT NULL, product text NOT NULL, external_id text NOT NULL, state text NOT NULL, expires_at timestamptz, PRIMARY KEY(source,external_id));
CREATE INDEX IF NOT EXISTS provision_jobs_ready ON provision_jobs(state,lease_until);
CREATE INDEX IF NOT EXISTS usage_workspace ON usage_reservations(workspace_id,created_at);
